#include "rib_fixture.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <QJsonDocument>
#include <BRepClass3d_SolidClassifier.hxx>
#include <iostream>
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 using namespace RibFixture;CadDocument d;auto args=make(d);const auto distal=args.take("farFeatureId").toString();check(std::abs(d.bodies().front().summary["volumeMm3"].toDouble()-5600)<1e-6,"U source volume");const auto before=d.authored();const auto target=args.value("targetBodyId");
 const auto draft=CadDocument::ribCandidate(before,args);const auto preview=CadDocument::evaluateCandidate(draft);check(preview.ok,preview.error+QString::fromUtf8(QJsonDocument(preview.diagnostics).toJson()));check(d.authored()==before,"preview detached");commit(d,draft);const auto body=d.bodies().front();check(d.bodies().size()==1 && body.bodyId==target && body.summary["valid"].toBool() && body.summary["closed"].toBool() && body.summary["topology"].toObject()["solids"]==1,"one valid closed retained target");check(std::abs(body.summary["volumeMm3"].toDouble()-7472)<1e-6,"Rib analytic 7472 volume and exact face-contact join");check(std::abs(body.summary["ribSpanMm"].toDouble()-27)<1e-7,"To Next depth");const auto ids=body.summary["ribSupportFaceIds"];check(ids.toArray().size()==2 && draft["features"].toArray().last().toObject()["parameters"].toObject()["supportFaceIds"]==ids,"pinned exact support pair");BRepClass3d_SolidClassifier sample(body.shape,{20,15,4},1e-7);check(sample.State()==TopAbs_IN,"rib center material");
 const auto accepted=d.authored();d.history().undo();check(d.authored()==before,"undo");d.history().redo();check(d.authored()==accepted,"redo");args["featureId"]=draft["features"].toArray().last().toObject().value("id");args["thicknessMm"]=3.;commit(d,CadDocument::ribCandidate(d.authored(),args));check(std::abs(d.bodies().front().summary["volumeMm3"].toDouble()-8408)<1e-6,"thickness edit");args["thicknessMm"]=2.;commit(d,CadDocument::ribCandidate(d.authored(),args));
 auto edited=d.authored();auto fs=edited["features"].toArray();for(int i=0;i<fs.size();++i){auto f=fs[i].toObject();if(f["id"]!=distal)continue;auto p=f["parameters"].toObject();p["yMm"]=26.;f["parameters"]=p;fs[i]=f;}edited["features"]=fs;commit(d,edited);check(std::abs(d.bodies().front().summary["volumeMm3"].toDouble()-7328)<1e-6 && d.bodies().front().summary["ribSupportFaceIds"]==ids,"wall spacing recompute with stable support identity");
 const auto stable=d.authored();const auto revision=d.revision();const auto undo=d.state().value("undo");auto refuse=stable;fs=refuse["features"].toArray();for(int i=0;i<fs.size();++i){auto f=fs[i].toObject();if(f["id"]!=distal)continue;auto p=f["parameters"].toObject();p["widthMm"]=20.;f["parameters"]=p;fs[i]=f;}refuse["features"]=fs;check(!d.commit(refuse,"Partial stop refusal").isEmpty(),"partial stop refused");check(d.lastEvaluationError()["code"]=="rib_support_unavailable" && d.authored()==stable && d.revision()==revision && d.state()["undo"]==undo,"atomic full-cover refusal");
 QTemporaryDir tmp;check(d.save(tmp.filePath("rib.alloy")).isEmpty(),"save");CadDocument reopened;check(reopened.open(tmp.filePath("rib.alloy")).isEmpty() && reopened.authored()==d.authored(),"reopen retained authored");check(std::abs(reopened.bodies().front().summary["volumeMm3"].toDouble()-7328)<1e-6,"reopen recompute");std::cout<<"PASS retained Rib: exact face-contact U join7472, thickness8408, wall edit7328, stable support/body identity, undo/redo/storage and atomic partial-stop refusal\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
